    public AwsBedrockAgentValidateFlowDefinitionOptions(
        string Definition
    )
    {
        global::System.ArgumentNullException.ThrowIfNull(Definition);
        this.Definition = Definition;
    }

    private AwsBedrockAgentValidateFlowDefinitionOptions()
    {
        _requiresAlternateInput = true;
    }

    public static AwsBedrockAgentValidateFlowDefinitionOptions FromCliInputJson(string cliInputJson)
    {
        global::System.ArgumentException.ThrowIfNullOrWhiteSpace(cliInputJson);
        return new() { CliInputJson = cliInputJson };
    }

    public static AwsBedrockAgentValidateFlowDefinitionOptions ForCliSkeleton(string generateCliSkeleton = "input") =>
        generateCliSkeleton is "input" or "yaml-input"
            ? new() { GenerateCliSkeleton = generateCliSkeleton }
            : throw new global::System.ArgumentOutOfRangeException(
                nameof(generateCliSkeleton),
                generateCliSkeleton,
                "Required operation values may only be omitted for input or yaml-input skeletons.");

    /// <summary>
    /// The definition of a flow to validate. nodes -&gt; (list) An array of node definitions in the flow. Constraints: o min: 0 o max: 40 (structure) Contains configurations about a node in the flow. name -&gt; (string) [required] A name for the node. Constraints: o pattern: [a-zA-Z]([_]?[0-9a-zA-Z]){1,50} type -&gt; (string) [required] The type of node. This value must match the name of the key that you provide in the configuration you provide in the FlowNodeConfiguration field. Possible values: o Input o Output o KnowledgeBase o Condition o Lex o Prompt o LambdaFunction o Storage o Agent o Retrieval o Iterator o Collector o InlineCode o Loop o LoopInput o LoopController configuration -&gt; (tagged union structure) Contains configurations for the node. NOTE: This is a Tagged Union structure. Only one of the fol- lowing top level keys can be set: input, output, knowledgeBase, condition, lex, prompt, lambdaFunction, storage, agent, retrieval, iterator, collector, in- lineCode, loop, loopInput, loopController. input -&gt; (structure) Contains configurations for an input flow node in your flow. The first node in the flow. inputs can't be specified for this node. output -&gt; (structure) Contains configurations for an output flow node in your flow. The last node in the flow. outputs can't be specified for this node. knowledgeBase -&gt; (structure) Contains configurations for a knowledge base node in your flow. Queries a knowledge base and returns the retrieved results or generated response. knowledgeBaseId -&gt; (string) [required] The unique identifier of the knowledge base to query. Constraints: o min: 0 o max: 10 o pattern: $|^[0-9a-zA-Z]+ modelId -&gt; (string) The unique identifier of the model or inference profile to use to generate a response from the query results. Omit this field if you want to re- turn the retrieved results as an array. Constraints: o min: 1 o max: 2048 o pattern: (arn:aws(-[^:]{1,12})?:(bedrock|sage- maker):[a-z0-9-]{1,20}:([0-9]{12})?:([a-z-]+/)?)?([a-zA-Z0-9.-]{1,63}){0,2}(([:][a-z0-9-]{1,63}){0,2})?(/[a-z0-9]{1,12})? guardrailConfiguration -&gt; (structure) Contains configurations for a guardrail to apply during query and response generation for the knowledge base in this configuration. guardrailIdentifier -&gt; (string) The unique identifier of the guardrail. Constraints: o min: 0 o max: 2048 o pattern: (([a-z0-9]+)|(arn:aws(-[^:]+)?:bedrock:[a-z0-9-]{1,20}:[0-9]{12}:guardrail/[a-z0-9]+)) guardrailVersion -&gt; (string) The version of the guardrail. Constraints: o pattern: (([0-9]{1,8})|(DRAFT)) numberOfResults -&gt; (integer) The number of results to retrieve from the knowl- edge base. Constraints: o min: 1 o max: 100 promptTemplate -&gt; (structure) A custom prompt template to use with the knowledge base for generating responses. textPromptTemplate -&gt; (string) The text of the prompt template. Constraints: o min: 1 o max: 100000 inferenceConfiguration -&gt; (tagged union structure) Contains inference configurations for the prompt. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: text. text -&gt; (structure) Contains inference configurations for a text prompt. temperature -&gt; (float) Controls the randomness of the response. Choose a lower value for more predictable outputs and a higher value for more sur- prising outputs. Constraints: o min: 0 o max: 1 topP -&gt; (float) The percentage of most-likely candidates that the model considers for the next to- ken. Constraints: o min: 0 o max: 1 maxTokens -&gt; (integer) The maximum number of tokens to return in the response. Constraints: o min: 0 stopSequences -&gt; (list) A list of strings that define sequences af- ter which the model will stop generating. Constraints: o min: 0 o max: 4 (string) rerankingConfiguration -&gt; (structure) The configuration for reranking the retrieved re- sults from the knowledge base to improve rele- vance. type -&gt; (string) [required] Specifies the type of reranking model to use. Currently, the only supported value is BEDROCK_RERANKING_MODEL . Possible values: o BEDROCK_RERANKING_MODEL bedrockRerankingConfiguration -&gt; (structure) Specifies the configuration for using an Amazon Bedrock reranker model to rerank retrieved re- sults. modelConfiguration -&gt; (structure) [required] Specifies the configuration for the Amazon Bedrock reranker model. modelArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the Amazon Bedrock reranker model. Constraints: o min: 1 o max: 2048 o pattern: (arn:aws(-[^:]+)?:bedrock:[a-z0-9-]{1,20}::foun- dation-model/(.*))? additionalModelRequestFields -&gt; (map) Specifies additional model-specific re- quest parameters as key-value pairs that are included in the request to the Ama- zon Bedrock reranker model. key -&gt; (string) Constraints: o min: 1 o max: 100 value -&gt; (document) numberOfRerankedResults -&gt; (integer) Specifies the number of results to return after reranking. Constraints: o min: 1 o max: 100 metadataConfiguration -&gt; (structure) Specifies how metadata fields should be handled during the reranking process. selectionMode -&gt; (string) [required] The mode for selecting metadata fields for reranking. Possible values: o SELECTIVE o ALL selectiveModeConfiguration -&gt; (tagged union structure) The configuration for selective metadata field inclusion or exclusion during reranking. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: fieldsToInclude, fieldsToExclude. fieldsToInclude -&gt; (list) Specifies the metadata fields to in- clude in the reranking process. Constraints: o min: 1 o max: 100 (structure) Specifies a metadata field to in- clude or exclude during the reranking process. fieldName -&gt; (string) [required] The name of the metadata field to include or exclude during reranking. Constraints: o min: 1 o max: 2000 fieldsToExclude -&gt; (list) Specifies the metadata fields to ex- clude from the reranking process. Constraints: o min: 1 o max: 100 (structure) Specifies a metadata field to in- clude or exclude during the reranking process. fieldName -&gt; (string) [required] The name of the metadata field to include or exclude during reranking. Constraints: o min: 1 o max: 2000 orchestrationConfiguration -&gt; (structure) The configuration for orchestrating the retrieval and generation process in the knowledge base node. promptTemplate -&gt; (structure) A custom prompt template for orchestrating the retrieval and generation process. textPromptTemplate -&gt; (string) The text of the prompt template. Constraints: o min: 1 o max: 100000 inferenceConfig -&gt; (tagged union structure) Contains inference configurations for the prompt. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: text. text -&gt; (structure) Contains inference configurations for a text prompt. temperature -&gt; (float) Controls the randomness of the response. Choose a lower value for more pre- dictable outputs and a higher value for more surprising outputs. Constraints: o min: 0 o max: 1 topP -&gt; (float) The percentage of most-likely candidates that the model considers for the next token. Constraints: o min: 0 o max: 1 maxTokens -&gt; (integer) The maximum number of tokens to return in the response. Constraints: o min: 0 stopSequences -&gt; (list) A list of strings that define sequences after which the model will stop generat- ing. Constraints: o min: 0 o max: 4 (string) additionalModelRequestFields -&gt; (map) The additional model-specific request parame- ters as key-value pairs to be included in the request to the foundation model. key -&gt; (string) Constraints: o min: 1 o max: 100 value -&gt; (document) performanceConfig -&gt; (structure) The performance configuration options for the knowledge base retrieval and generation process. latency -&gt; (string) The latency optimization setting. Possible values: o standard o optimized condition -&gt; (structure) Contains configurations for a condition node in your flow. Defines conditions that lead to different branches of the flow. conditions -&gt; (list) [required] An array of conditions. Each member contains the name of a condition and an expression that defines the condition. Constraints: o min: 1 o max: 5 (structure) Defines a condition in the condition node. name -&gt; (string) [required] A name for the condition that you can ref- erence. Constraints: o pattern: [a-zA-Z]([_]?[0-9a-zA-Z]){1,50} expression -&gt; (string) Defines the condition. You must refer to at least one of the inputs in the condition. For more information, expand the Condition node section in Node types in prompt flows . Constraints: o min: 1 o max: 64 lex -&gt; (structure) Contains configurations for a Lex node in your flow. Invokes an Amazon Lex bot to identify the intent of the input and return the intent as the output. botAliasArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the Amazon Lex bot alias to invoke. Constraints: o min: 0 o max: 78 o pattern: $|^arn:aws(-cn|-us-gov|-eusc|-iso(-[b-f])?)?:lex:([a-z]{2,}-){2,}\d:\d{12}:bot-alias/[0-9a-zA-Z]+/[0-9a-zA-Z]+ localeId -&gt; (string) [required] The Region to invoke the Amazon Lex bot in. Constraints: o min: 0 o max: 10 prompt -&gt; (structure) Contains configurations for a prompt node in your flow. Runs a prompt and generates the model response as the output. You can use a prompt from Prompt man- agement or you can configure one in this node. sourceConfiguration -&gt; (tagged union structure) [re- quired] Specifies whether the prompt is from Prompt man- agement or defined inline. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: re- source, inline. resource -&gt; (structure) Contains configurations for a prompt from Prompt management. promptArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the prompt from Prompt management. Constraints: o pattern: $|^(arn:aws(-cn|-us-gov|-eusc|-iso(-[b-f])?)?:bedrock:[a-z0-9-]{1,20}:[0-9]{12}:prompt/[0-9a-zA-Z]{10}(?::[0-9]{1,5})?) inline -&gt; (structure) Contains configurations for a prompt that is defined inline templateType -&gt; (string) [required] The type of prompt template. Possible values: o TEXT o CHAT templateConfiguration -&gt; (tagged union struc- ture) [required] Contains a prompt and variables in the prompt that can be replaced with values at runtime. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: text, chat. text -&gt; (structure) Contains configurations for the text in a message for a prompt. text -&gt; (string) [required] The message for the prompt. Constraints: o min: 1 cachePoint -&gt; (structure) A cache checkpoint within a template configuration. type -&gt; (string) [required] Indicates that the CachePoint- Block is of the default type Possible values: o default inputVariables -&gt; (list) An array of the variables in the prompt template. Constraints: o min: 0 o max: 20 (structure) Contains information about a variable in the prompt. name -&gt; (string) The name of the variable. Constraints: o pattern: ([0-9a-zA-Z][_-]?){1,100} chat -&gt; (structure) Contains configurations to use the prompt in a conversational format. messages -&gt; (list) [required] Contains messages in the chat for the prompt. (structure) A message input or response from a model. For more information, see Create a prompt using Prompt management . role -&gt; (string) [required] The role that the message be- longs to. Possible values: o user o assistant content -&gt; (list) [required] The content in the message. (tagged union structure) Contains the content for the message you pass to, or receive from a model. For more information, see Create a prompt using Prompt management . NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: text, cachePoint. text -&gt; (string) The text in the mes- sage. cachePoint -&gt; (structure) Creates a cache check- point within